import java.util.List;

/**
 * A simple model of a Grass plant.
 * Grass age, breed and die.
 *
 * @version 2022.03.01
 */
public class Grass extends Plants
{
    // The age at which a grass plant can start to grow.
    private static final int BREEDING_AGE = 1;
    // The age to which a grass plant can live.
    private static final int MAX_AGE = 200;
    // The maximum number of sqaures new grass can grow into.
    private static final int MAX_LITTER_SIZE = 500;

    /**
     * Create a new grass plant at location in field.
     *
     * @param randomAge True if a random age should be generated for the grass
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Grass(boolean randomAge, Field field, Location location)
    {
        super(field, location);
        setAge(0);
        if(randomAge) {
            setAge(getRandom().nextInt(MAX_AGE));
        } 
        setGrowthLevel(getAge()/50.0);
    }

    /**
     * Make this plant act - that is: make it do
     * whatever it wants/needs to do.
     * 
     * @param newGrass A list to receive newly born grass.
     * @param simulator The simulator.
     */
    public void act(List<Actor> newGrass,Simulator simulator){
        incrementAge(simulator.getSteps());
        setGrowthLevel(0.05);
        if(!simulator.isDay() || !isActive()){
            return;
        }

        restorePlantPresence();
        applyWeatherEffects(simulator.getWeather());
        spread(newGrass, simulator.getSteps());
    }

    /**
     * Restore this grass plant to its location after any occupying actor moves away.
     */
    private void restorePlantPresence()
    {
        Field field = getField();
        Object occupant = field.getObjectAt(getLocation());
        if(occupant == null){
            setLocation(getLocation());
        }
        else if(occupant != this && occupant instanceof Plants){
            Plants grassPlant = (Plants) occupant;
            grassPlant.setDead();
            setLocation(getLocation());
        }
    }

    /**
     * Update water and sun levels based on the current weather.
     * @param weather The current weather.
     */
    private void applyWeatherEffects(Weather weather)
    {
        switch(weather){
            case SUNNY:
                increaseSunLevel();
                decreaseWaterLevel();
                break;
            case RAINY:
                increaseWaterLevel();
                decreaseSunLevel();
                break;
            case FOGGY:
                increaseWaterLevel();
                break;
            default:
                break;
        }
    }

    /**
     * Spread to adjacent free locations when growth conditions are met.
     * @param newGrass A list to receive newly born grass.
     * @param step The current simulation step.
     */
    private void spread(List<Actor> newGrass, int step)
    {
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = growth(step);
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Grass young = new Grass(false, field, loc);
            newGrass.add(young);
        }
    }

    /**
     * Get breeding age of a grass.
     * @return int. Breeding age of the grass.
     */
    protected int getBreedingAge(){
        return BREEDING_AGE;
    }

    /**
     * Get max age of a grass.
     * @return int. Maximum age of the grass.
     */
    protected int getMaxAge(){
        return MAX_AGE;
    }

    /**
     * Get max litter size of a grass.
     * @return int. Maximum litter size of the grass;
     */
    protected int getMaxLitter(){
        return MAX_LITTER_SIZE;
    }
}

import java.util.HashMap;
import java.util.Map;

/**
 * This class collects and provides some statistical data on the state 
 * of a field. It is flexible: it will create and maintain a counter 
 * for any class of object that is found within the field.
 *
 * @version 2022.03.01
 */
public class FieldStats
{
    // Counters for each type of entity (jaguar, gazelle, etc.) in the simulation.
    private Map<Class<?>, Counter> counters;
    // Whether the counters are currently up to date.
    private boolean countsValid;

    /**
     * Construct a FieldStats object.
     */
    public FieldStats()
    {
        // Set up a collection for counters for each type of animal that
        // we might find
        counters = new HashMap<>();
        countsValid = true;
    }

    /**
     * Get details of what is in the field.
     * @param field The field currently occupied.
     * @param simulator. The current simulator the simulation is being run on.
     * @return A string listing what is in the field.
     */
    public String getPopulationDetails(Field field, Simulator simulator)
    {
        StringBuilder buffer = new StringBuilder();
        ensureCountsValid(field, simulator);
        for(Counter info : counters.values()) {
            buffer.append(info.getName());
            buffer.append(": ");
            buffer.append(info.getCount());
            buffer.append(' ');
        }
        return buffer.toString();
    }

    /**
     * Invalidate the current set of statistics; reset all 
     * counts to zero.
     */
    public void reset()
    {
        countsValid = false;
        for(Counter count : counters.values()) {
            count.reset();
        }
    }

    /**
     * Increment the count for one class of actor.
     * @param actor The object of animal to increment.
     * @param simulator. The current simulator the simulation is being run on.
     */
    public void incrementCount(Object actor, Simulator simulator)
    {
        Class<?> actorClass = actor.getClass();
        Counter count = getCounter(actorClass);
        count.increment();
        if(simulator.getSteps() != 0 && actor instanceof Grass){
            count.setCount(simulator.getNoOfGrass());
        }
    }

    /**
     * Indicate that an actor count has been completed.
     */
    public void countFinished()
    {
        countsValid = true;
    }

    /**
     * Determine whether the simulation is still viable.
     * I.e., should it continue to run.
     * @param field The field currently occupied.
     * @param simulator The current simulator the simulation is being run on.
     * @return true If there is more than one species alive.
     */
    public boolean isViable(Field field, Simulator simulator)
    {
        ensureCountsValid(field, simulator);
        return countNonZeroSpecies() > 1;
    }

    /**
     * Generate counts of the number of all animals.
     * These are not kept up to date as all animals
     * are placed in the field, but only when a request
     * is made for the information.
     * @param field The field to generate the stats for.
     * @param simulator The current simulator the simulation is being run on.
     */
    private void generateCounts(Field field, Simulator simulator)
    {
        reset();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    incrementCount(animal, simulator);
                }
            }
        }
        countsValid = true;
    }

    /**
     * Ensure the current counts are populated before they are read.
     * @param field The field currently occupied.
     * @param simulator The current simulator the simulation is being run on.
     */
    private void ensureCountsValid(Field field, Simulator simulator)
    {
        if(!countsValid) {
            generateCounts(field, simulator);
        }
    }

    /**
     * Get or create the counter associated with an actor type.
     * @param actorClass The actor class to track.
     * @return The matching counter.
     */
    private Counter getCounter(Class<?> actorClass)
    {
        Counter count = counters.get(actorClass);
        if(count == null) {
            count = new Counter(actorClass.getName());
            counters.put(actorClass, count);
        }
        return count;
    }

    /**
     * Count the number of actor types with a non-zero population.
     * @return The number of species with active members.
     */
    private int countNonZeroSpecies()
    {
        int nonZero = 0;
        for(Counter info : counters.values()) {
            if(info.getCount() > 0) {
                nonZero++;
            }
        }
        return nonZero;
    }
}

